style.css:
@-moz-document domain("open.spotify.com") {
/* Set a custom background image */
    body {
        background: url('https://i.pinimg.com/736x/8a/6c/38/8a6c38bd2a400f48cd39f697cb3631f6.jpg') no-repeat center center fixed !important;
        background-size: cover !important;
        color: #ffffff !important; /* Text color */
    }

    /* Optional: Add a semi-transparent overlay for better contrast */
    body::before {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.5); /* Black overlay with 50% transparency */
        z-index: -1;
    }

    /* Change the header background to match */
    .Root__top-bar {
        background: rgba(0, 0, 0, 0.8) !important; /* Semi-transparent header */
        border-bottom: 2px solid #6272a4 !important;
    }

    /* Customize player bar background */
    .main-nowPlayingBar-container {
        background: rgba(0, 0, 0, 0.7) !important;
        border-top: 2px solid #6272a4 !important;
    }

    /* Adjust playlist item colors */
    .main-rootlist-rootlistItem {
        background: rgba(0, 0, 0, 0.5) !important;
        color: #bd93f9 !important;
    }

    .main-rootlist-rootlistItem:hover {
        background: rgba(0, 0, 0, 0.7) !important;
        color: #ffffff !important;
    }
}
